package com.booksyde.controller; import com.booksyde.exception.BusinessException; import com.booksyde.service.GoogleDriveService; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/integrations/google-drive") public class GoogleDriveController {private final GoogleDriveService s;public GoogleDriveController(GoogleDriveService s){this.s=s;} @PostMapping("/folder") public ResponseEntity<String> folder(@RequestBody Map<String,String> b){String id=s.folderId(b.get("folderUrl"));if(id==null)throw new BusinessException("Link de pasta do Google Drive inválido.");return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(s.list(id));} @GetMapping("/files/{fileId}") public ResponseEntity<byte[]> file(@PathVariable String fileId){if(!fileId.matches("^[a-zA-Z0-9_-]+$"))throw new BusinessException("Arquivo inválido.");var r=s.file(fileId);if(r.statusCode()/100!=2)throw new BusinessException("Google Drive recusou o arquivo.");return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).cacheControl(CacheControl.noStore()).body(r.body());}}